  <div><div class="fs-5 fw-semibold"><?= e($m['number']) ?> — <?= e($m['title']) ?></div><div class="small text-secondary"><?= e($m['destination']) ?> · <?= e(fdate($m['start_date'], false)) ?> → <?= e(fdate($m['end_date'], false)) ?> · <?= e($m['projet_code']) ?> · <?= e($m['conv_number']) ?> / <?= e($m['ligne_code']) ?> <?= e($m['ligne']) ?></div></div>
