  <?php if ($m['report']): ?><div class="card mb-3"><div class="card-header"><i class="bi bi-journal-text"></i> <?= e(t('Rapport de mission')) ?></div><div class="card-body small"><?= nl2br(e($m['report'])) ?></div></div><?php endif; ?>
