  <div class="card mb-3"><div class="card-body small"><div class="d-flex justify-content-between"><span><?= e(t('Chef de mission')) ?></span><b><?= e($m['chef']) ?></b></div><div class="d-flex justify-content-between"><span><?= e(t('Véhicule')) ?></span><b><?= e($m['plate'] ? $m['plate'] . ' — ' . $m['vehicule'] : '—') ?></b></div>
    <div class="d-flex justify-content-between"><span><?= e(t('Demandée par')) ?></span><b><?= e($m['author']) ?></b></div><div class="d-flex justify-content-between"><span><?= e(t('Approuvée par')) ?></span><b><?= e($m['approver'] ?: '—') ?></b></div>
