    <div class="col-12"><select name="compte_id" class="form-select form-select-sm" required><?php foreach ($comptes as $k): ?><option value="<?= (int) $k['id'] ?>"><?= e($k['name']) ?> (<?= money($k['balance']) ?>)</option><?php endforeach; ?></select></div>
    <?= ong_field('amount', 'Montant', max(0, (float) $m['estimate'] - (float) $m['advance']) ?: '', 'text', 'required inputmode="decimal"', 'col-6') ?><?= ong_field('op_date', 'Date', date('Y-m-d'), 'date', '', 'col-6') ?><div class="col-12"><button class="btn btn-sm btn-primary"><i class="bi bi-cash"></i> <?= e(t('Verser l\'avance')) ?></button></div></form></div></div><?php endif; ?>
  <?php if ($st === 'approuvee' && can('ong.depenses')): ?><div class="card mb-3"><div class="card-body"><form method="post" action="<?= $act('depart') ?>"><?= csrf_field() ?><button class="btn btn-primary"><i class="bi bi-play-fill"></i> <?= e(t('Enregistrer le départ')) ?></button> <span class="small text-secondary"><?= e(t('Le véhicule passe « en mission ».')) ?></span></form></div></div><?php endif; ?>
  <?php if ($st === 'en_cours' && can('ong.depenses')): ?><div class="card mb-3"><div class="card-header"><?= e(t('Retour de mission')) ?></div><div class="card-body"><form method="post" action="<?= $act('retour') ?>"><?= csrf_field() ?><textarea name="report" class="form-control form-control-sm mb-2" rows="6" required minlength="20" placeholder="<?= e(t('Rapport : activités réalisées, résultats, personnes rencontrées, difficultés, recommandations.')) ?>"></textarea><button class="btn btn-dark"><i class="bi bi-flag"></i> <?= e(t('Enregistrer le retour et le rapport')) ?></button></form></div></div><?php endif; ?>
  <?php if ($st === 'terminee' && can('ong.tresorerie')): ?><div class="card mb-3 border-dark"><div class="card-header"><?= e(t('Justifier l\'avance et clôturer')) ?></div><div class="card-body"><form method="post" action="<?= $act('cloturer') ?>" class="row g-2"><?= csrf_field() ?>
    <p class="small mb-1"><?= e(t('Saisissez le total des frais justifiés par des pièces. Le reliquat est reversé sur le compte ; un dépassement est payé en complément. Les frais sont imputés à la ligne budgétaire.')) ?></p>
    <?= ong_field('justified', 'Total justifié', (float) $m['advance'], 'text', 'required inputmode="decimal"', 'col-6') ?><?= ong_field('piece', 'Référence des pièces', '', 'text', 'maxlength="80"', 'col-6') ?>
    <div class="col-12"><label class="form-label small mb-0"><?= e(t('Compte (reliquat ou complément)')) ?></label><select name="compte_id" class="form-select form-select-sm"><?php foreach ($comptes as $k): ?><option value="<?= (int) $k['id'] ?>"><?= e($k['name']) ?> (<?= money($k['balance']) ?>)</option><?php endforeach; ?></select></div>
    <div class="col-12"><button class="btn btn-sm btn-success"><i class="bi bi-lock"></i> <?= e(t('Clôturer la mission')) ?></button></div></form></div></div><?php endif; ?>
  <?php if (in_array($st, ['demandee', 'approuvee'], true) && can('ong.approve')): ?><div class="card"><div class="card-body"><form method="post" action="<?= $act('annuler') ?>" class="d-flex gap-2"><?= csrf_field() ?><input name="reason" class="form-control form-control-sm" required minlength="3" maxlength="255" placeholder="<?= e(t('Motif de l\'annulation')) ?>"><button class="btn btn-sm btn-outline-danger text-nowrap"><?= e(t('Annuler la mission')) ?></button></form></div></div><?php endif; ?>
</div></div>
